import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        List<String> isi = new ArrayList<>();
        while (in.hasNextLine()) {
            isi.add(in.nextLine());
        }
        Path p = Paths.get("belanja-nio.txt");
        Files.write(p, isi);
        List<String> baris = Files.readAllLines(p);
        Collections.sort(baris);
        Files.write(p, baris);
        for (String b : Files.readAllLines(p)) {
            System.out.println(b);
        }
    }
}
